import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { InstructorConsole } from "./CourseEntry";

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(
  <React.StrictMode>
    {window.location.pathname.replace(/\/+$/, "") === "/admin"
      ? <InstructorConsole standalone onClose={() => window.location.assign("/")} />
      : <App />}
  </React.StrictMode>
);
